import { createHash } from 'node:crypto';
import { buildStarter } from './starter.mjs';

const fingerprint = value => typeof value === 'string' && /^sha256:[a-f0-9]{64}$/.test(value);
const document = (schemaVersion, resources) => ({ schemaVersion,
  revision: createHash('sha256').update(JSON.stringify(resources)).digest('hex'), resources });

// Inspection receipts are generated by VerdFlow's public package readers, never by executing a strategy.
export function buildImportDocuments(selection, entries, inspection) {
  if (selection?.schemaVersion !== 1 || !Array.isArray(selection.resources) || selection.resources.length > 32
      || inspection?.schemaVersion !== 1 || !Array.isArray(inspection.resources)) throw Error('Invalid import inputs');
  const resources = [];
  const seen = new Set();
  const owners = new Map();
  for (const { record } of entries) {
    for (const release of record.versions) {
      if (release.status !== 'published' || (record.type !== 'strategies' && release.version !== record.recommended)) continue;
      const facts = inspection.resources.filter(item => item.id === record.id && item.version === release.version);
      if (facts.length !== 1) throw Error(`Missing or ambiguous package inspection: ${record.id}@${release.version}`);
      const fact = facts[0];
      const expected = { id: record.id, name: record.name, kind: record.type, version: release.version,
        ...release.package, page_url: `https://mr-pardon.github.io/verdflow-resources/?type=${record.type}&id=${record.id}&version=${release.version}` };
      for (const [key, value] of Object.entries(expected)) {
        if (fact[key] !== value) throw Error(`Stale package inspection: ${record.id}.${key}`);
      }
      if (record.type === 'strategies' && !fingerprint(fact.strategy_hash)) throw Error('Missing strategy content fingerprint');
      if (record.type === 'assets' && !['dts', 'blender'].includes(fact.target_type)) throw Error('Missing catalog target');
      if (record.type === 'plans' && (!fact.plan || fact.plan.profile_id !== release.package.identity
          || !fingerprint(fact.plan.semantic_hash) || !fingerprint(fact.plan.strategy_hash)
          || typeof fact.plan.strategy_id !== 'string' || typeof fact.plan.strategy_version !== 'string' || !Array.isArray(fact.plan.catalogs))) {
        throw Error('Missing inspected plan dependency');
      }
      const identity = `${record.type}/${fact.target_type || ''}/${release.package.identity}/${release.version}`;
      if (seen.has(identity)) throw Error('Ambiguous package ownership');
      seen.add(identity);
      const owner = `${record.type}/${fact.target_type || ''}/${release.package.identity}`;
      if (owners.has(owner) && owners.get(owner) !== record.id) throw Error('Ambiguous package ownership');
      owners.set(owner, record.id);
      resources.push({ ...expected, status: 'published',
        ...(record.type === 'strategies' ? { strategy_hash: fact.strategy_hash } : {}),
        ...(record.type === 'assets' ? { target_type: fact.target_type } : {}),
        ...(record.type === 'plans' ? { plan: fact.plan } : {}) });
    }
  }
  const selectedIds = new Set();
  const selected = selection.resources.map(item => {
    const record = entries.find(entry => entry.record.id === item.id)?.record;
    const version = item.version === 'recommended' ? record?.recommended : item.version;
    const match = resources.find(resource => resource.id === item.id && resource.version === version);
    if (!match || selectedIds.has(item.id)) throw Error(`Invalid starter selection: ${item.id}`);
    selectedIds.add(item.id);
    return match;
  });
  const v1Selection = { ...selection, resources: selection.resources.filter(item =>
    entries.find(entry => entry.record.id === item.id)?.record.type !== 'plans') };
  return { legacy: buildStarter(v1Selection, entries), starter: document(2, selected), index: document(1, resources) };
}
